head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > parent]<br/>주어진 DOM 요소에서 지정한 횟수만큼 상위 노드를 탐색하여 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 부모 노드를 검색할 DOM 요소를 설정할 수 있어야 합니다.",
        "number(선택) 파라미터로 상위 노드를 탐색할 횟수를 설정할 수 있어야 합니다.",
        "number(선택) 파라미터 생략 시 기본값 1로 동작하여 한 단계 상위 부모 노드를 반환해야 합니다.",
        "지정한 횟수만큼 상위의 부모 노드를 반환해야 합니다.",
        "탐색 도중 element 가 null 이 되면 null 을 반환해야 합니다.",
    ]
}



scwin.comp_init = async function () {
    if (typeof grp_depth1 !== 'undefined') {
        grp_depth1.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    $c.gcm.createLabel('label="구조: grp_depth1 / grp_depth2 / grp_depth3 / txt_target"', '', 'label1');

    // grp_depth1 > grp_depth2 > grp_depth3 > txt_target (4단계 중첩)
    let strDepth1 = '<xf:group ' + ns + ' style="border:1px solid #ccc; padding:5px;"></xf:group>';
    scwin.grp_depth1 = await $p.dynamicCreate('grp_depth1', 'group', strDepth1, grp_comp);

    let strDepth2 = '<xf:group ' + ns + ' style="border:1px solid #aaa; padding:5px;"></xf:group>';
    scwin.grp_depth2 = await $p.dynamicCreate('grp_depth2', 'group', strDepth2, scwin.grp_depth1);

    let strDepth3 = '<xf:group ' + ns + ' style="border:1px solid #888; padding:5px;"></xf:group>';
    scwin.grp_depth3 = await $p.dynamicCreate('grp_depth3', 'group', strDepth3, scwin.grp_depth2);

    let strTarget = '<w2:textbox ' + ns + ' label="탐색 대상 (txt_target)" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_target', 'textbox', strTarget, scwin.grp_depth3);
}



scwin.onpageload = async function () {
    $c.gcm.createCommonDatalist();
    await scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_parent_onclick = function () {
    let element = document.querySelector("[id*='txt_target']");
    let numberVal = par_number.getValue();

    let ret;
    if (numberVal === '') {
        // number 파라미터 생략 (기본값 1 적용)
        ret = WebSquare.util.parent(element);
    } else {
        ret = WebSquare.util.parent(element, Number(numberVal));
    }

    let result = [];
    if (ret) {
        result.push("tagName: " + ret.tagName);
        result.push("id: " + (ret.id || '(없음)'));
    } else {
        result.push("반환값: null");
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
